/**
 * @name Insecure reflection via getattr/setattr
 * @description Using getattr or setattr with untrusted input can lead to arbitrary attribute access
 * @kind path-problem
 * @problem.severity warning
 * @id py/insecure-reflection
 * @tags security
 *        external/cwe/cwe-470
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ReflectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // getattr(object, name, ...)
    exists(API::CallNode call |
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // setattr(object, name, value)
    exists(API::CallNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // hasattr(object, name)
    exists(API::CallNode call |
      call = API::builtin("hasattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // delattr(object, name)
    exists(API::CallNode call |
      call = API::builtin("delattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module ReflectionFlow = TaintTracking::Global<ReflectionConfig>;
import ReflectionFlow::PathGraph

from ReflectionFlow::PathNode source, ReflectionFlow::PathNode sink
where ReflectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure reflection from $@.", source.getNode(), "user input"

/**
 * @name Information disclosure via logging
 * @description Logging sensitive data can lead to information disclosure
 * @kind problem
 * @problem.severity warning
 * @id py/information-disclosure
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module InfoDisclosureConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Logging sensitive data
    exists(API::CallNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      call = API::moduleImport("print").getACall() and
      sink = call.getArg(0)
    )
