}

module InfoDisclosureFlow = TaintTracking::Global<InfoDisclosureConfig>;

from DataFlow::Node source, DataFlow::Node sink
where InfoDisclosureFlow::flow(source, sink)
select sink, "Sensitive data may be logged or printed: $@", source, "user input"

/**
 * @name Potential injection via dictionary operations
 * @description Dictionary operations with untrusted keys/values could lead to injection
 * @kind problem
 * @problem.severity warning
 * @id py/dictionary-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module DictInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Dictionary operations that might use keys/values in unsafe ways
    exists(API::CallNode call |
      // str.format with dictionary unpacking
      call = API::builtin("str").getMember("format").getACall() and
      exists(DataFlow::Node arg | arg = call.getArg(0) and sink = arg)
    )
    or
    exists(API::CallNode call |
      // f-string evaluation
      call = API::builtin("eval").getACall() and
      exists(DataFlow::Node arg | arg = call.getArg(0) and sink = arg)
    )
    or
    exists(API::CallNode call |
      // Template string substitution
      call = API::moduleImport("string").getMember("Template").getMember("substitute").getACall() and
      exists(DataFlow::Node arg | arg = call.getArg(0) and sink = arg)
    )
  }
}

module DictInjectionFlow = TaintTracking::Global<DictInjectionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where DictInjectionFlow::flow(source, sink)
select sink, "Untrusted data used in dictionary-based string operation: $@", source, "user input"
